<script setup>
import DataTable from "../../shared/components/DataTable.vue"

import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()



import {computed, onActivated, onDeactivated, onBeforeUnmount, onMounted, ref, watch} from 'vue'
import {useRoute, useRouter} from 'vue-router'
import {api, openWorkspace, post, stamp} from '../api.js'
import {toast} from '../../shared/composables/toast.js'


import PageHeader from '../../shared/components/PageHeader.vue'
import ListFilters from '../../shared/components/ListFilters.vue'
import HelpTip from '../../shared/components/HelpTip.vue'
import WorkDeliveryEditor from '../../deploy/components/WorkDeliveryEditor.vue'
import ResolveWorkItemDialog from '../components/ResolveWorkItemDialog.vue'
import ReleaseMarkDialog from '../components/ReleaseMarkDialog.vue'
import {workOrigin} from '../navigation.js'
import {fieldLabel, issueStatus, sourcePerson, severityLabels, priorityLabels} from '../issueFields.js'
import {issueDate} from '../../shared/issuePresentation.js'
import {browserView} from '../../shared/viewMemory.js'
defineOptions({name:'ResearchWorkItems'})
const props=defineProps({embedded:Boolean,initialMine:Boolean})
const route=useRoute(),router=useRouter(),busy=ref(false),opening=ref(''),page=ref(1),data=ref({items:[],total:0,page:1,total_exact:true}),people=ref([]),q=ref(''),status=ref(''),kind=ref(''),person=ref(''),role=ref('assigned_to'),intent=ref(''),mine=ref(false),me=ref({aliases:[]}),quick=ref('all'),severity=ref(''),priority=ref(''),resolution=ref(''),order=ref('updated_desc'),advanced=ref(false),dictionaries=ref({}),sources=ref([]),source=ref(''),product=ref('0'),productNames=ref({}),peopleNames=ref({}),loadError=ref(''),cursors=ref([''])
let queryGeneration=0,queryController,viewMemory,viewReady=false
const viewDefaults={q:'',status:'',kind:'',person:'',role:'assigned_to',intent:'',mine:false,quick:'all',severity:'',priority:'',resolution:'',order:'updated_desc',advanced:false,source:'',product:'0',relation:''}
function rememberView(){if(viewReady)viewMemory?.write(Object.fromEntries(Object.entries(viewFields).map(([key,value])=>[key,value.value])),viewDefaults)}
const releaseMarkRecord=ref(null)
async function openReleaseMark(w){if(opening.value||!hasIdentity.value)return;const key=w.source+':'+(w.external_id||w.id);opening.value=key;try{const item=w.id?w:await post('research/work-items/attach',{connection:w.source.slice(7),external_id:w.external_id,kind:w.kind});const state=await api('research/work-items/'+item.id+'/release-mark');if(!state.can_mark){toast('仅相关成员或管理员可维护已上线标记','warning');return}releaseMarkRecord.value={item:{...w,...item},mark:state.mark,target:!w.release_mark?.marked}}catch(e){toast(e.message,'error')}finally{opening.value=''}}
function releaseMarkSaved(){releaseMarkRecord.value=null;load(true);if(window.parent!==window)window.parent.postMessage({type:'work-item.changed'},location.origin)}
const resolving=ref(null),deliveryItem=ref(null),deliveryOpen=ref(false),deliveryServices=ref([]),deliveryMe=ref({})
const canManageDelivery=value=>deliveryMe.value.role==='admin'||value?.owner===deliveryMe.value.username
const relation=ref(''),followingBusy=ref('')
const viewFields={q,status,kind,person,role,intent,mine,quick,severity,priority,resolution,order,advanced,source,product,relation}
watch(Object.values(viewFields),rememberView,{flush:'post'})
function resolveState(value){if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',...value},location.origin)}
function resolved(){resolving.value=null;load()}
const remoteSource=computed(()=>source.value&&source.value!=='manual')
const selectedSource=computed(()=>sources.value.find(s=>s.name===source.value))
// Use the live source dictionary for both row labels and raw-code filters.
// Replace fields rather than retaining labels from an earlier identity/read.
watch(data,result=>{if(remoteSource.value&&result.field_labels){const key='zentao:'+source.value;dictionaries.value={...dictionaries.value,[key]:{...dictionaries.value[key],...result.field_labels}}}},{flush:'sync'})
const productOptions=computed(()=>[{value:'0',label:'全部产品'},...(selectedSource.value?.products||[]).map(id=>({value:String(id),label:productNames.value[id]||'产品 #'+id}))])
const sourceOptions=computed(()=>[{value:'',label:'全部来源'},{value:'manual',label:'平台自建'},...sources.value.map(s=>({value:s.name,label:s.name+'（Bug）'}))])
const advancedCount=computed(()=>[person.value,severity.value,priority.value,resolution.value,intent.value,remoteSource.value&&product.value!=='0'?product.value:''].filter(Boolean).length)
const filtered=computed(()=>!!(q.value||status.value||person.value||severity.value||priority.value||resolution.value||intent.value||mine.value||quick.value!=='all'||order.value!=='updated_desc'||kind.value))
const nextAvailable=computed(()=>data.value.has_more??page.value*20<data.value.total)
const enumOptions=key=>{const base=key==='severity'?severityLabels:priorityLabels,map=new Map(Object.entries(base));for(const d of Object.values(dictionaries.value))for(const [value,label] of Object.entries(d[key]||{}))map.set(value,label);for(const w of data.value.items)if(w[key])map.set(String(w[key]),fieldLabel(w,key,dictionaries.value));return [...map].map(([value,label])=>({value,label}))}
const quickViews=[{value:'all',label:'全部'},{value:'assigned',label:'指派给我'},{value:'participating',label:'我参与的'},{value:'following',label:'我关注的'},{value:'release',label:'与我相关的待上线'},{value:'resolved',label:'由我解决'},{value:'undecided',label:'上线待确认'}]
const hasIdentity=computed(()=>me.value.auth_enabled!==false&&me.value.actor&&me.value.actor!=='local')
const resolutions=computed(()=>{const map=new Map();for(const d of Object.values(dictionaries.value))for(const [value,label] of Object.entries(d.resolution||{}))map.set(value,label);for(const w of data.value.items)if(w.resolution)map.set(w.resolution,fieldLabel(w,'resolution',dictionaries.value));return [...map].map(([value,label])=>({value,label}))})
async function load(reset=false){const generation=++queryGeneration;queryController?.abort();const controller=new AbortController();queryController=controller;busy.value=true;loadError.value='';if(reset){page.value=1;cursors.value=['']}try{const query=new URLSearchParams({relation:relation.value,connection:source.value,product:remoteSource.value?product.value:'',mine:mine.value?'1':'',q:q.value,status:status.value,kind:kind.value,person:person.value,person_role:role.value,release_required:intent.value,severity:severity.value,priority:priority.value,resolution:resolution.value,order:order.value,page:page.value,page_size:20,cursor:cursors.value[page.value-1]||''});if(quick.value==='release')query.set('delivery','pending_release');const result=await api('research/work-items/page?'+query,{signal:controller.signal});if(generation!==queryGeneration)return;data.value=result;page.value=result.page;if(result.query_mode==='candidate_batch'){productNames.value={...(result.products||{}),...productNames.value};peopleNames.value={...peopleNames.value,...(result.people||{})}}else{productNames.value=result.products||{};peopleNames.value=result.people||{}}people.value=Object.keys({...(!remoteSource.value?me.value.assignees||{}:{}),...peopleNames.value}).filter(p=>p&&p!=='closed');cursors.value[page.value]=result.next_cursor||''}catch(e){if(generation!==queryGeneration||controller.signal.aborted)return;data.value={items:[],total:0,page:page.value,has_more:false};loadError.value=e.message;toast(e.message,'error',{duration:6000})}finally{if(generation===queryGeneration)busy.value=false}}
function sourceChanged(){relation.value='';queryGeneration++;product.value='0';productNames.value={};peopleNames.value={};people.value=[];person.value='';mine.value=false;quick.value='all';kind.value=remoteSource.value?'bug':'';intent.value='';status.value='';load(true)}
function myAccount(){return me.value.connections?.find(c=>c.name===source.value)?.account||me.value.aliases.find(a=>people.value.includes(a))||me.value.actor}
function chooseQuick(value,query=true){if(value!=='all'&&!hasIdentity.value){toast('请先登录平台，再使用我的筛选','warning');return}quick.value=value;relation.value=['participating','following'].includes(value)?value:['release','undecided'].includes(value)?'related':'';mine.value=value!=='all'&&!relation.value;person.value=mine.value?myAccount():'';role.value=value==='resolved'?'resolved_by':'assigned_to';status.value=value==='assigned'?'active':'';intent.value=value==='release'?'yes':value==='undecided'?'unknown':'';if(query)load(true)}
async function follow(w){if(followingBusy.value)return;if(!hasIdentity.value){toast('请先登录后关注工作项','warning');return}const key=w.source+':'+(w.external_id||w.id);followingBusy.value=key;try{const item=w.id?w:await post('research/work-items/attach',{connection:w.source.slice(7),external_id:w.external_id,kind:w.kind});const result=await post('research/work-items/'+item.id+'/follow',{following:!w.following},'PUT');w.id=item.id;w.following=result.following;toast(result.following?'已关注；转派后仍可追踪交付':'已取消关注，不影响参与记录','success');if(quick.value==='following'&&!result.following)load()}catch(e){toast(e.message,'error')}finally{followingBusy.value=''}}
function onlyMine(){relation.value='';if(!hasIdentity.value){toast('请先登录平台并关联本人来源账号','warning');return}mine.value=!mine.value;quick.value=mine.value?'assigned':'all';person.value=mine.value?myAccount():'';load(true)}
function reset(){relation.value='';q.value='';status.value='';kind.value=remoteSource.value?'bug':'';person.value='';role.value='assigned_to';intent.value='';severity.value='';priority.value='';resolution.value='';order.value='updated_desc';mine.value=false;quick.value='all';load(true)}
const columnSort=field=>({sortDirections:['ascend','descend'],sorter:true,sortOrder:order.value===field+'_asc'?'ascend':order.value===field+'_desc'?'descend':''})
function sort(field,direction){order.value=direction?field+(direction==='ascend'?'_asc':'_desc'):'updated_desc';load(true)}
function changePage(value){page.value=value;load()}
async function open(item,action=''){if(opening.value)return;if(action==='resolve'){resolving.value=item;return}const key=item.source+':'+(item.external_id||item.id);opening.value=key;try{const reference=item.source.startsWith('zentao:')?await post('research/work-items/attach',{connection:item.source.slice(7),external_id:item.external_id,kind:item.kind}):item;if(action==='changes'){[deliveryServices.value,deliveryMe.value]=await Promise.all([api('services'),api('/api/me')]);deliveryItem.value={...item,...reference};deliveryOpen.value=true;return}await router.push({path:'/work/'+reference.id,query:{...(action?{action}:{}),...(props.embedded?{return:'inbox'}:{}),return_to:workOrigin(route,props.embedded)}})}catch(e){toast(e.message,'error')}finally{opening.value=''}}
function personLabel(value,item){return sourcePerson(value,item?.source==='manual'?me.value.people||{}:peopleNames.value)}
function changed(e){if(e.origin===location.origin&&e.data?.type==='work-item.changed')load()}
onActivated(()=>{if(data.value.items.length)load()})
onDeactivated(()=>resolving.value=null)
onMounted(async()=>{
 window.addEventListener('message',changed)
 try{
  [me.value,sources.value]=await Promise.all([api('research/overview'),api('research/work-items/sources')])
  source.value=sources.value.find(s=>s.name===route.query.connection)?.name||'';product.value='0';kind.value=remoteSource.value?'bug':''
  dictionaries.value=Object.fromEntries((me.value.connections||[]).map(c=>['zentao:'+c.name,c.field_labels||{}]))
  if((props.initialMine||route.query.mine==='1')&&hasIdentity.value){mine.value=true;quick.value='assigned';person.value=myAccount()}
  viewMemory=browserView('research:work:'+(props.embedded?'personal':'all'),me.value.actor||'local')
  const remembered=viewMemory.read({...viewDefaults,...Object.fromEntries(Object.entries(viewFields).map(([key,value])=>[key,value.value]))})
  for(const [key,value] of Object.entries(remembered))viewFields[key].value=value
  if(!sourceOptions.value.some(s=>s.value===source.value)){source.value='';product.value='0';person.value='';mine.value=false;quick.value='all';relation.value=''}
  if(!hasIdentity.value){mine.value=false;relation.value='';quick.value='all'}
  if(quickViews.some(v=>v.value===route.query.quick)){q.value='';severity.value='';priority.value='';resolution.value='';chooseQuick(route.query.quick,false)}
  viewReady=true;await load()
 }catch(e){loadError.value=e.message;toast(e.message,'error')}
})
onBeforeUnmount(()=>{rememberView();++queryGeneration;queryController?.abort();window.removeEventListener('message',changed)})
defineExpose({reload:load})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Badge,Button,Card,CardAction,CardContent,CardFooter,CardHeader,CardTitle,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsList,TabsTrigger} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon,ArrowUpIcon,ArrowDownIcon,ArrowUpDownIcon} from '@lucide/vue'
</script>
<template><section :class="{'embedded-work-list':embedded}" class="research-work-items "><PageHeader v-if="!embedded" title="需求与 Bug"><template #actions><Button variant="outline" @click="router.push('/work/delivery')">待上线与批量交付</Button><Button @click="router.push({path:'/work/new',query:{return_to:workOrigin(route)}})" variant="default" size="default" type="button">＋ 新建工作项</Button></template></PageHeader><div class="work-quick-filters mb-5 flex min-w-0 items-start gap-2 border-b pb-0.5"><Tabs class="min-w-0" :model-value="quick" @update:model-value="chooseQuick($event)"><TabsList variant="line" class="h-auto! max-w-full flex-wrap gap-y-1"><TabsTrigger class="h-9" v-for="v in quickViews" :key="v.value" :value="v.value">{{v.label}}</TabsTrigger></TabsList></Tabs><div class="shrink-0 pt-1"><HelpTip text="来源连接与平台自建均支持需求和 Bug，可按类型筛选。默认查询允许范围内的全部产品，来源平台统一筛选和排序。与我相关的待上线是参与或关注的生产交付候选。已关闭、测试成功不代表已上线；可人工标记已上线，误操作可在全部列表撤销。生产由环境用途配置决定。"/></div></div><ListFilters v-model="advanced" :active-count="advancedCount"><InputGroup  class="min-w-0 "><InputGroupInput v-model="q" placeholder="搜索标题或编号" @keyup.enter="load(true)" v-bind="{'aria-label':'搜索工作项'}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="q" :disabled="false" size="icon-xs" aria-label="清空输入" @click="q='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="source" :options="sourceOptions" :style="{width:'180px',maxWidth:'100%'}" aria-label="工作项来源" :disabled="!!opening" @change="sourceChanged"/><OptionPicker v-model="kind" :options="[{value:'bug',label:'Bug'},{value:'requirement',label:'需求'}]" :all-label="remoteSource?undefined:'全部类型'" aria-label="工作项类型" :style="{width:'120px',maxWidth:'100%'}"/><OptionPicker v-model="status" :options="[{value:'active',label:'激活'},{value:'resolved',label:'已解决'},{value:'closed',label:'已关闭'},{value:'open',label:'未关闭'}]" all-label="全部状态" :style="{width:'120px',maxWidth:'100%'}"/><template #actions><Button v-if="filtered" @click="reset" variant="ghost" size="default" type="button">重置筛选</Button><Button @click="load(true)" variant="default" size="default" type="button" :disabled="(busy)"><Spinner v-if="busy"/>搜索</Button></template><template #advanced><Field v-if="remoteSource"><FieldLabel as="div">产品</FieldLabel><OptionPicker v-model="product" :options="productOptions"  :style="{width:'190px',maxWidth:'100%'}" :disabled="!!opening" @change="load(true)"/></Field><Field ><FieldLabel as="div">人员关系</FieldLabel><OptionPicker v-model="role" :options="[{value:'assigned_to',label:'指派给'},{value:'resolved_by',label:'由谁解决'},{value:'opened_by',label:'由谁创建'},{value:'closed_by',label:'由谁关闭'}]" :style="{width:'130px',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">人员</FieldLabel><OptionPicker v-model="person" :options="people.map(p=>({value:p,label:(!remoteSource&&(me.people||{})[p]||peopleNames[p])?(!remoteSource&&(me.people||{})[p]||peopleNames[p])+'（'+p+'）':p}))" all-label="全部人员"  :style="{width:'170px',maxWidth:'100%'}" :disabled="mine"/></Field><Button @click="onlyMine" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[mine?'primary':'secondary']||'outline'" size="default" type="button">只看我的</Button><Field ><FieldLabel as="div">级别</FieldLabel><OptionPicker v-model="severity" :options="enumOptions('severity')" all-label="全部级别" :style="{width:'130px',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">优先级</FieldLabel><OptionPicker v-model="priority" :options="enumOptions('priority')" all-label="全部优先级" :style="{width:'130px',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">方案</FieldLabel><OptionPicker v-model="resolution" :options="resolutions" all-label="全部方案"  :style="{width:'180px',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">上线意图</FieldLabel><OptionPicker v-model="intent" :options="[{value:'yes',label:'需上线'},{value:'no',label:'无需上线'},{value:'unknown',label:'上线待确认'}]" all-label="全部上线意图" :style="{width:'150px',maxWidth:'100%'}"/></Field><Button @click="load(true)" variant="outline" size="default" type="button" :disabled="(busy)"><Spinner v-if="busy"/>应用筛选</Button></template></ListFilters><div class="work-list-context r-muted">{{source?'实时查询 · '+source:'实时查询 · 全部来源'}}<template v-if="data.checked_at"> · {{stamp(data.checked_at)}}</template></div><div :aria-busy="busy" class="r-table"><div class="research-work-table console-table min-w-0 max-w-full"><div v-if="busy" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({minWidth:1616}).y?({minWidth:1616}).y+'px':undefined}"><DataTable :rows="(((data.items)||[]).map((w,rowIndex)=>({...w,__rowKey:w.source+':'+(w.external_id||w.id)}))||[])" :columns="[{id:'c0',label:&quot;编号 / 类型&quot;,size:104,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:'left'},{id:'c1',label:&quot;标题&quot;,size:300,minSize:160,required:true,defaultHidden:false,flex:true,selection:false,pin:'left'},{id:'c2',label:&quot;状态&quot;,size:76,minSize:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c3',label:&quot;指派给&quot;,size:96,minSize:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c4',ariaSort:((columnSort('severity'))?.sortOrder==='ascend'?'ascending':(columnSort('severity'))?.sortOrder==='descend'?'descending':'none'),label:&quot;级别&quot;,size:72,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c5',ariaSort:((columnSort('priority'))?.sortOrder==='ascend'?'ascending':(columnSort('priority'))?.sortOrder==='descend'?'descending':'none'),label:&quot;优先级&quot;,size:88,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c6',label:&quot;解决人&quot;,size:Math.max(80,Math.min(160,112)),minSize:64,required:false,defaultHidden:true,flex:false,selection:false,pin:false},{id:'c7',ariaSort:((columnSort('resolution'))?.sortOrder==='ascend'?'ascending':(